import assert from 'node:assert/strict';
import {randomUUID} from 'node:crypto';
import {writeFileSync} from 'node:fs';
const origin=process.env.THEMES_AUDIT_ORIGIN;
if(!origin) throw new Error('Dedicated synthetic main HTTP origin required');
const themeId=process.env.THEMES_AUDIT_THEME;
const cookies={}, checks=[];
async function req(who,method,path,body,version,status=200){
 const r=await fetch(origin+'/api/v1'+path,{method,headers:{'X-Request-Id':randomUUID(),'X-Data-Mode':'live',...(cookies[who]?{Cookie:cookies[who]}:{}),...(body?{'Content-Type':'application/json'}:{}),...(method==='POST'?{'Idempotency-Key':randomUUID()}:{}),...(version?{'If-Match':`"${version}"`}:{})},...(body?{body:JSON.stringify(body)}:{})});
 if(path==='/session')cookies[who]=r.headers.get('set-cookie').split(';')[0];
 const data=r.status===204?null:await r.json();assert.equal(r.status,status,JSON.stringify({path,data}));return data;
}
for(const key of ['self','friend','outsider'])await req(key,'POST','/session',{profileKey:key},null,201);
const friend=(await req('friend','GET','/me')).data.id;
let t=(await req('self','GET','/themes/'+themeId)).data;
const mediaId=t.coverMediaId, records=t.recordIds;
assert.ok(mediaId);assert.equal(records.length,2);
const settings=(await req('friend','GET','/me/settings')).data;
await req('friend','PATCH','/me/settings',{profileVisibility:'public'},settings.version);
const friendship=randomUUID();
await req('self','POST','/friendships',{id:friendship,recipientId:friend},null,201);
await req('friend','PATCH','/friendships/'+friendship,{status:'accepted'},1);
async function share(visibility,sharedWith=[]){const s=(await req('self','GET','/themes/'+themeId+'/sharing')).data;await req('self','PATCH','/themes/'+themeId+'/sharing',{visibility,sharedWith},s.version);}
await share('private');
await req('self','GET','/shared-themes/'+themeId);
for(const key of ['friend','outsider'])await req(key,'GET','/shared-themes/'+themeId,null,null,404);
checks.push('private: owner 200, accepted friend and outsider 404');
await share('selected',[friend]);
let visible=(await req('friend','GET','/shared-themes/'+themeId)).data;
assert.deepEqual(visible.recordIds,[]);assert.equal(visible.coverMedia,null);assert.deepEqual(visible.sharing.sharedWith,[]);
await req('outsider','GET','/shared-themes/'+themeId,null,null,404);
await req('friend','GET','/media/'+mediaId,null,null,404);
assert.ok((await req('friend','GET','/shared-themes?audience=friends')).items.some(x=>x.id===themeId));
checks.push('selected: friend sees theme but no private records/media/recipient IDs; outsider 404');
const record=(await req('self','GET','/records/'+records[0])).data.record;
await req('self','PATCH','/records/'+record.id,{visibility:'selected',sharedWith:[friend]},record.version);
visible=(await req('friend','GET','/shared-themes/'+themeId)).data;
assert.deepEqual(visible.recordIds,[record.id]);assert.equal(visible.coverMedia.id,mediaId);
await req('outsider','GET','/media/'+mediaId,null,null,404);
checks.push('selected record: friend gets only permitted record and cover; outsider media 404');
await share('public');
visible=(await req('outsider','GET','/shared-themes/'+themeId)).data;
assert.deepEqual(visible.recordIds,[]);assert.equal(visible.coverMedia,null);
checks.push('public theme does not expose selected/private member records or photo');
await share('private');
await req('friend','GET','/shared-themes/'+themeId,null,null,404);
const updated=(await req('self','GET','/records/'+record.id)).data.record;
await req('self','PATCH','/records/'+record.id,{visibility:'private',sharedWith:[]},updated.version);
const base={visitId:null,placeId:null,occurredAt:null,endedAt:null,timePrecision:'unknown',purposes:[],activities:[],impression:'',periodAnswers:{},bookmarked:false,useForSuggestions:true,topicKey:null,visibility:'private',sharedWith:[]};
const memo={name:'合成メモ一覧確認',originRefs:[{type:'record',id:record.id,version:updated.version+1}],keywords:['散歩']};
const created=(await req('self','POST','/records',{...base,id:randomUUID(),kind:'memo',body:'次回は木陰で休む',memo},null,201)).data;
const list=await req('self','GET','/records?kind=memo&includeUndated=true');
assert.deepEqual(list.items.find(x=>x.id===created.id).memo,memo);
checks.push('own memo list retains name/origin version/keywords and independent body');
const result={checkedAt:new Date().toISOString(),origin,themeId,mediaId,memoId:created.id,checks};
writeFileSync(new URL('./acceptance-http-20260927.json',import.meta.url),JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result));
